<script setup lang="ts">
import SourceReference from './SourceReference.vue';
import {computed,ref,watch,nextTick} from 'vue';
import ConnectionBuilder from './ConnectionBuilder.vue';
import {type Context,type Limits,type Repertoire,type Element,type ProgramEntry,fetchJson} from './api';
import {type Locale,formName} from './i18n';
import {guidance} from './manual-text';
const props=defineProps<{context?:Context;limits:Limits;repertoire?:Repertoire;locale:Locale;excludedConnections?:string[];allowMixedDirections?:boolean}>();
type Entry=ProgramEntry;
const emit=defineEmits<{change:[entries:Entry[],complete:boolean]}>();
const copy={en:{search:'Find an element by name or code',add:'Add',remove:'Remove',up:'Move up',down:'Move down',retain:'Retain for calculation',connection:'Build a connection',next:'Next part',finish:'Add connection',reset:'Start again',complete:'Program is fully described',draft:'Draft',compliant:'Construction complies with category rules',noncompliant:'Construction breaks category rules',input_unavailable:'Input cannot be assessed',checking:'Assessing…',failed:'Assessment unavailable. Try again.',personal:'Personal conflicts',category:'Category findings',violation:'Check this category rule',conflict:'Conflicts with your limits',total:'Credited BV',sequence:'Direct step into Axel assumed',retry:'Try again'},de:{search:'Element nach Name oder Code suchen',add:'Hinzufügen',remove:'Entfernen',up:'Nach oben',down:'Nach unten',retain:'Für Berechnung beibehalten',connection:'Verbindung zusammenstellen',next:'Nächster Teil',finish:'Verbindung hinzufügen',reset:'Neu beginnen',complete:'Programm vollständig beschrieben',draft:'Entwurf',compliant:'Aufbau entspricht den Kategorieregeln',noncompliant:'Aufbau verletzt Kategorieregeln',input_unavailable:'Eingabe nicht auswertbar',checking:'Wird geprüft…',failed:'Prüfung nicht verfügbar. Erneut versuchen.',personal:'Persönliche Konflikte',category:'Kategoriehinweise',violation:'Diese Kategorieregel prüfen',conflict:'Widerspricht deinen Grenzen',total:'Angerechneter Basiswert',sequence:'Direkter Schritt in den Axel angenommen',retry:'Erneut versuchen'},ru:{search:'Найти элемент по названию или коду',add:'Добавить',remove:'Удалить',up:'Вверх',down:'Вниз',retain:'Сохранить для расчёта',connection:'Составить соединение',next:'Следующая часть',finish:'Добавить соединение',reset:'Начать заново',complete:'Программа полностью описана',draft:'Черновик',compliant:'Построение соответствует правилам категории',noncompliant:'Построение нарушает правила категории',input_unavailable:'Невозможно оценить ввод',checking:'Проверка…',failed:'Оценка недоступна. Повторите попытку.',personal:'Личные ограничения',category:'Замечания по категории',violation:'Проверьте это правило категории',conflict:'Противоречит вашим ограничениям',total:'Зачтённая базовая стоимость',sequence:'Предполагается прямой шаг в аксель',retry:'Повторить'}};
const labels=computed(()=>copy[props.locale]);const query=ref(''),entries=ref<Entry[]>([]),complete=ref(false);
const picker=ref<HTMLDialogElement>(),pickerButton=ref<HTMLButtonElement>();
const pickerLabels=computed(()=>({en:{open:'Add an element',close:'Done'},de:{open:'Element hinzufügen',close:'Fertig'},ru:{open:'Добавить элемент',close:'Готово'}}[props.locale]));
async function openPicker(){picker.value?.showModal();await nextTick();picker.value?.querySelector<HTMLInputElement>('input')?.focus();}
interface Part{code:string;form:string;level:number|null}
interface Finding{translationKey?:string;setting?:string|string[];maximum?:number;entryId?:string;ruleId?:string;source?:import('./api').Source}
interface Assessment{requestId:string;revision:number;construction:'draft'|'compliant'|'noncompliant'|'input_unavailable';totalHundredths:number|null;elements:{entryId:string;creditedHundredths:number|null;outcome:string;parts:Part[]}[];categoryFindings:Finding[];personalConflicts:Finding[]}
function message(key?:string){return guidance[props.locale][key as keyof typeof guidance.en]??labels.value.violation;}
function partName(part:Part){return `${part.form==='Eu'?message('Eu'):formName(props.locale,part.form)}${part.level==null?'':` ${part.level===0?'B':part.level}`}`;}
function entryName(entry:Entry){const parts=assessment.value?.elements.find(e=>e.entryId===entry.id)?.parts;const solo=props.repertoire?.elements.find(e=>e.code===entry.code);return parts?.map(partName).join(' + ')??(solo?formName(props.locale,solo.form):entry.code);}
const assessment=ref<Assessment>(),checking=ref(false),failed=ref(false),inputFailure=ref(false);let revision=0,timer:ReturnType<typeof setTimeout>;
const matches=computed(()=>props.repertoire?.elements.filter(e=>`${e.code} ${formName(props.locale,e.form)}`.toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))??[]);
const number=(value:number|null|undefined)=>value==null?'—':new Intl.NumberFormat(props.locale,{minimumFractionDigits:2,maximumFractionDigits:2}).format(value/100);
function add(e:Pick<Element,'key'|'code'>){entries.value.push({id:crypto.randomUUID(),elementKey:e.key,code:e.code,retained:false});picker.value?.close();}
async function edit(index:number,move:number){const id=entries.value[index]!.id;if(move===0)entries.value.splice(index,1);else{const[entry]=entries.value.splice(index,1);entries.value.splice(index+move,0,entry!);}await nextTick();document.querySelector<HTMLElement>(`[data-entry-id="${move===0?entries.value[Math.min(index,entries.value.length-1)]?.id:id}"] button:not(:disabled)`)?.focus();}
async function assess(own:number){if(!props.context)return;const requestId=crypto.randomUUID();failed.value=false;inputFailure.value=false;try{const result=await fetchJson<Assessment>('/api/v1/program-assessments',{requestId,revision:own,context:props.context,personalLimits:props.limits,entries:entries.value.map(({id,elementKey})=>({id,elementKey})),submission:complete.value?'complete':'draft',excludedConnections:props.excludedConnections??[],allowMixedDirections:props.allowMixedDirections??false});if(own===revision&&result.revision===own&&result.requestId===requestId)assessment.value=result;}catch(error){if(own===revision){failed.value=true;inputFailure.value=error instanceof Error&&["assessment_input_unavailable","invalid_element_key","context_unavailable"].includes(error.message);}}finally{if(own===revision)checking.value=false;}}
function schedule(){const own=++revision;assessment.value=undefined;clearTimeout(timer);checking.value=true;timer=setTimeout(()=>assess(own),120);}
watch([entries,complete,()=>props.context,()=>props.limits,()=>props.excludedConnections,()=>props.allowMixedDirections],()=>{emit('change',entries.value.map(e=>({...e})),complete.value);schedule();},{deep:true});
function replaceEntries(next:ProgramEntry[],fullyDescribed=complete.value){entries.value=next.map(entry=>({...entry}));complete.value=fullyDescribed;}
defineExpose({replaceEntries});
</script>
<template>
<div class="manual-editor"><button ref="pickerButton" data-testid="open-element-picker" class="manual-search" @click="openPicker">{{pickerLabels.open}}</button>
<dialog ref="picker" class="element-picker" :aria-label="pickerLabels.open" @close="pickerButton?.focus()"><div class="picker-heading"><h2>{{pickerLabels.open}}</h2><button data-testid="close-element-picker" @click="picker?.close()">{{pickerLabels.close}}</button></div><label class="manual-search">{{labels.search}}<input data-testid="element-query" v-model="query" type="search"></label>
<ul class="element-choices" data-testid="repertoire"><li v-for="e in matches" :key="e.key"><code>{{e.code}}</code><span>{{formName(locale,e.form)}}</span><span>{{number(e.baseHundredths)}}</span><button :data-testid="`add-${e.code}`" @click="add(e)">{{labels.add}} {{e.code}}</button></li></ul>
<ConnectionBuilder :context="context" :limits="limits" :locale="locale" :excluded-connections="excludedConnections" :allow-mixed-directions="allowMixedDirections" @select="add" />
</dialog>
<ol class="program-list"><li v-for="(entry,index) in entries" :key="entry.id" data-testid="program-entry" :data-entry-id="entry.id"><code>{{entry.code}}</code><span>{{entryName(entry)}}</span><span>{{number(assessment?.elements.find(e=>e.entryId===entry.id)?.creditedHundredths)}}</span><label><input type="checkbox" v-model="entry.retained">{{labels.retain}}</label><div class="entry-actions"><button :disabled="index===0" :aria-label="labels.up" @click="edit(index,-1)">↑</button><button :disabled="index===entries.length-1" :aria-label="labels.down" @click="edit(index,1)">↓</button><button :aria-label="labels.remove" @click="edit(index,0)">×</button></div></li></ol>
<label><input type="checkbox" v-model="complete">{{labels.complete}}</label><div data-testid="assessment"><div role="status" aria-live="polite"><p v-if="checking">{{labels.checking}}</p><p v-else-if="failed">{{inputFailure?labels.input_unavailable:labels.failed}} <button @click="schedule">{{labels.retry}}</button></p><template v-else-if="assessment"><p>{{labels[assessment.construction]}} · {{labels.total}}: <strong>{{number(assessment.totalHundredths)}}</strong></p></template></div><template v-if="assessment&&!checking&&!failed"><details v-if="assessment.categoryFindings.length"><summary>{{labels.category}} ({{assessment.categoryFindings.length}})</summary><ul><li v-for="(f,i) in assessment.categoryFindings" :key="i">{{message(f.translationKey)}} <details><summary>{{f.ruleId}}</summary><span v-if="f.entryId">{{entries.find(e=>e.id===f.entryId)?.code}}</span><small v-if="f.source"><SourceReference :source="f.source" :locale="locale" /></small></details></li></ul></details><details v-if="assessment.personalConflicts.length"><summary>{{labels.personal}} ({{assessment.personalConflicts.length}})</summary><ul><li v-for="(f,i) in assessment.personalConflicts" :key="i">{{entries.find(e=>e.id===f.entryId)?.code}}: {{message(f.translationKey)}} · {{Array.isArray(f.setting)?f.setting.join(", "):f.setting}} {{f.maximum??""}}</li></ul></details></template></div></div>
</template>
